    SetValueExecuteExt(env, (void *)asyncCallbackInfo, asyncCallbackInfo->uri);
    ani_boolean retVal = true;
    if (asyncCallbackInfo->status <= 0) {
        ThrowError(env, asyncCallbackInfo->status);
        retVal = false;
