        SETTING_LOG_INFO("helper is null");
        asyncCallbackInfo->status = STATUS_ERROR_CODE;
        return;
    }

    OHOS::DataShare::DataShareValuesBucket val;
    val.Put(SETTINGS_DATA_FIELD_KEYWORD, asyncCallbackInfo->key);
