void ThrowExistingError(napi_env env, int errorCode, std::string errorMessage)
{
    napi_value code;
    napi_value message;
    napi_value error;
    napi_create_uint32(env, errorCode, &code);
    napi_create_string_utf8(env, errorMessage.c_str(), NAPI_AUTO_LENGTH, &message);
