            if (asyncCallbackInfo != nullptr) {
                DeleteCallbackInfo(env, asyncCallbackInfo);
                asyncCallbackInfo = nullptr;
            }
        }
        return promise;
    } else {
        SETTING_LOG_ERROR("INVALID CALL");
