        return render->getExternalTexture();
    } else {
        ELOGV("render not init");
        return -1; //未初始化
    }
}

void yyeva::RenderController::renderFrame() {
    glClearColor(0, 0, 0, 0);
    glClear(GL_COLOR_BUFFER_BIT);
    if (videoRecord) { //视频录制使用fbo后的纹理作为传输
        //获取录制使用的FrameBuffer
        glBindFramebuffer(GL_FRAMEBUFFER, mFrameBuffer);
    }
    if (bgRender != nullptr) {
        bgRender->renderFrame();
    }
    if (render != nullptr) {
        render->renderFrame();
    }
    if (videoRecord) {
        if (!config->isMix) {
            glBindFramebuffer(GL_FRAMEBUFFER, GL_NONE);
            if (fbRender != nullptr) {
                fbRender->renderFrame();
            }
        }
    }
}

void yyeva::RenderController::renderSwapBuffers() {
    if (bgRender != nullptr) {
        bgRender->swapBuffers();
    }
    if (render != nullptr) {
        render->swapBuffers();
    }
    if (fbRender != nullptr) {
        fbRender->swapBuffers();
    }
    if (eglCore != nullptr) {
        eglCore->swapBuffer();
    }
}

void yyeva::RenderController::renderClearFrame() {
    if (bgRender != nullptr) {
        bgRender->clearFrame();
    }
    if (render != nullptr) {
        render->clearFrame();
    }
    if (fbRender != nullptr) {
        fbRender->clearFrame();
    }
    if (eglCore != nullptr) {
        eglCore->swapBuffer();
    }
}

void yyeva::RenderController::releaseTexture() {
    if (bgRender != nullptr) {
        bgRender->releaseTexture();
    }
    if (render != nullptr) {
        render->releaseTexture();
    }
    if (fbRender != nullptr) {
        fbRender->releaseTexture();
    }
    if (videoRecord) {
        destroyRecordFrameBuffer();
        videoRecord = false;
    }
}

