static bool PushTypedParameter(lua_State* L, napi_value arg, const std::string& format)
{
    napi_valuetype resultType;
    napi_typeof(g_env, arg, &resultType);

    switch (resultType) {
        case napi_boolean:
            if (format == "%d") {
