// 辅助函数：处理参数（T2lCallFunction版本）
static bool PushParameters(lua_State* L, napi_value argv[], int argc)
{
    for (int i = 1; i < argc; i++) {
        auto arg = argv[i];
        napi_valuetype resultType;
        napi_typeof(g_env, arg, &resultType);

        switch (resultType) {
