// 辅助函数：获取函数名
static std::string GetFunctionName(napi_env env, napi_value argv0)
{
    char buf[512] = {0};
    size_t sizeBuff = sizeof(buf);
    size_t result = 0;
    auto status = napi_get_value_string_utf8(env, argv0, buf, sizeBuff, &result);
    if (status != napi_ok) {
        return "";
