    jsonStr.append("\"");
    jsonStr.append("}");
    LOGD("handleMUCParticipantPresence ===>>>> %s %s \n", nick.c_str(), flagType.c_str());
    ThreadSafeInfoMUCP *data = &g_threadInfoMUCP;
    if (data == nullptr) {
