        OH_LOG_Print(LOG_APP, LOG_ERROR, LOG_DOMAIN, LOG_TAG, "get_socket: 未找到对应的 client");
        return nullptr;
    }
    if (client->nsp.empty()) {
        return client->clientInstance->socket();
    } else {
        return client->clientInstance->socket(client->nsp);
    }
}

