sio::socket::ptr SocketIOClient::get_socket(const std::string& classIdStr) const
{
    SocketIOClient *client = getClient(classIdStr);
    if (!client) {
        OH_LOG_Print(LOG_APP, LOG_ERROR, LOG_DOMAIN, LOG_TAG, "get_socket: 未找到对应的 client");
