}

napi_value SocketIOClient::connect(napi_env env, napi_callback_info info)
{
    size_t charLen = 0;
    size_t argc = 2;
    napi_value args[2] = {nullptr};
    napi_get_cb_info(env, info, &argc, args, nullptr, nullptr);
    char uri[MAX_BUF_SIZE];
