    std::string classIdStr = classId;
    SocketIOClient *client = getClient(classIdStr);
    if (!client) { return nullptr; }
    client->clientInstance.set_open_listener(std::bind(&ClientSocket::OnOpen, &g_clientSocket));

    return 0;
}

