			s = SQRT(bone->b * bone->b + bone->d * bone->d);
			if (s != 0) s = (s + (SQRT(tb * tb + td * td) - s + self->data->offsetScaleY) * mixScaleY) / s;
			bone->b *= s;
			bone->d *= s;
