static void CompleteWork(napi_env env, napi_value callback, void* ctx, void* data)
{
    napi_status status = napi_ok;
    CallbackContext *context = (CallbackContext *)data;
    if (context->type == CallbackType::CLICK) {
        napi_value resTxt;
        napi_create_string_utf8(env, context->clickData.c_str(), context->clickData.size(), &resTxt);
        status = napi_call_function(env, nullptr, callback, 1, &resTxt, nullptr);
        delete context;
        return;
    }

    if (context && context->vapState == VapState::FAILED) {
        constexpr int32_t paramSize = 2;
        napi_value ret[paramSize];
        ret[0] = NVal::CreateInt64(env, context->vapState).val_;
        ret[1] = NVal::CreateInt64(env, context->vapState).val_;
        napi_value res = nullptr;
        status = napi_call_function(env, nullptr, callback, paramSize, ret, &res);
    } else if (context && (context->vapState == VapState::RENDER || context->vapState == VapState::START)) {
        auto animConfig = NVal::CreateObject(env);
        CreateAnimConfig(env, context->jsAnimConfig, animConfig);
        constexpr int32_t paramSize = 2;
        napi_value ret[paramSize];
        ret[0] = NVal::CreateInt64(env, context->vapState).val_;
        ret[1] = animConfig.val_;
        napi_value res = nullptr;
        status = napi_call_function(env, nullptr, callback, paramSize, ret, &res);
    } else if (context) {
        napi_value rev = NVal::CreateInt64(env, context->vapState).val_;
        napi_value res = nullptr;
        status = napi_call_function(env, nullptr, callback, 1, &rev, &res);
    }
    delete context;
}

napi_threadsafe_function PluginRender::CreateThreadsafeFun(napi_env env, napi_value callback)
{
    napi_threadsafe_function tsfn_ { nullptr };
    napi_value resource_name;
    napi_create_string_utf8(env, "VapCallback", NAPI_AUTO_LENGTH, &resource_name);
    napi_create_threadsafe_function(
        env,
        callback,
        nullptr,
        resource_name,
        0,
        1,
        nullptr,
        [](napi_env env, void* finalize_data, void* finalize_hint) {},
        nullptr,
        CompleteWork,
        &tsfn_);
    return tsfn_;
}

napi_value PluginRender::Play(napi_env env, napi_callback_info info)
{
    LOGD("enter Play");
    std::string id = "";
    NFuncArg funcArg(env, info);
    if (!funcArg.InitArgs(NARG_CNT::ONE, NARG_CNT::FOUR)) {
        return nullptr;
    }

    napi_value v1 = funcArg.GetArg(NARG_POS::FIRST);
    NVal nVal(env, v1);
    auto [succ, resData, length] = nVal.ToUTF8String();
    std::string str = resData.get();

    if (funcArg.GetMaxArgc() >= FOUR) {
        napi_value jsId = funcArg.GetArg(NARG_POS::FOURTH);
        NVal idVal(env, jsId);
        auto [succ, resData, length] = idVal.ToUTF8String();
        id = resData.get();
    }

    if (id.empty()) {
        return nullptr;
    }

    std::shared_ptr<PluginRender> render = PluginRender::GetInstance(id);
    if (render) {
        std::string uri = str;
        if (uri.empty()) {
            LOGE("Play: uri empty");
            return nullptr;
        }
        VAPInfo info;
        std::map<std::string, MixInputData> mixData;
        if (funcArg.GetMaxArgc() >= TWO) {
            ParseMixParam(mixData, env, funcArg);
        }
        if (render->player_ == nullptr) {
            return nullptr;
        }
        if (funcArg.GetMaxArgc() >= THREE) {
            render->player_->SetCallback(CallbackType::PLAY_DONE,
                                         CreateThreadsafeFun(env, funcArg.GetArg(NARG_POS::THIRD)));
        }
        info.uri = uri;
        info.window = static_cast<NativeWindow*>(render->m_window);
        info.width = render->m_width;
        info.height = render->m_height;
        info.iptData = mixData;
        render->player_->Init(info);
        LOGD("Player Start executed");
    }
    return nullptr;
}

napi_value PluginRender::On(napi_env env, napi_callback_info info)
{
    NFuncArg funcArg(env, info);
    if (!funcArg.InitArgs(NARG_CNT::TWO, NARG_CNT::THREE)) {
        return nullptr;
    }

    napi_value v1 = funcArg.GetArg(NARG_POS::THIRD);
    NVal nVal(env, v1);
    auto [succ, resData, length] = nVal.ToUTF8String();
    std::string id = resData.get();

    std::shared_ptr<PluginRender> render = PluginRender::GetInstance(id);
    if (render && render->player_) {
        if (render->player_->IsRunning()) {
            LOGE("the player is running...plz call this func before play.");
            return nullptr;
        }
        napi_value v1 = funcArg.GetArg(NARG_POS::FIRST);
        NVal nVal(env, v1);
        auto [succ, resData, length] = nVal.ToUTF8String();
        std::string str = resData.get();
        LOGD("Get Count of argc %{public}zu str:%{public}s", funcArg.GetMaxArgc(), str.c_str());
        if (str != "stateChange" && str != "click") {
            LOGE("not support event");
            return nullptr;
        }

        if (str == "click") {
            render->player_->SetCallback(CallbackType::CLICK,
                                         CreateThreadsafeFun(env, funcArg.GetArg(NARG_POS::SECOND)));
        } else if (str == "stateChange") {
            render->player_->SetCallback(CallbackType::STATE_CHANGE,
                                         CreateThreadsafeFun(env, funcArg.GetArg(NARG_POS::SECOND)));
        }
    }
    return nullptr;
}

napi_value PluginRender::Off(napi_env env, napi_callback_info info)
{
    NFuncArg funcArg(env, info);
    if (!funcArg.InitArgs(NARG_CNT::ONE, NARG_CNT::TWO)) {
        LOGE("func 'off' Init args error.");
        return nullptr;
    }
    napi_value jsId = funcArg.GetArg(NARG_POS::SECOND);
    NVal nVal(env, jsId);
    auto [succ, resData, length] = nVal.ToUTF8String();
    std::string id = resData.get();
    LOGD("Off listener id:%{public}s", id.c_str());
    if (id.empty()) {
        LOGE("GetXComponentId error");
        return nullptr;
    }
    std::shared_ptr<PluginRender> render = PluginRender::GetInstance(id);
    if (render) {
        if (render->player_->IsRunning()) {
            LOGE("the player is running...plz call this func before play.");
            return nullptr;
        }
        napi_value v1 = funcArg.GetArg(NARG_POS::FIRST);
        NVal nVal(env, v1);
        auto [succ, resData, length] = nVal.ToUTF8String();
        std::string str = resData.get();
        LOGD("Get Count of argc %{public}zu str:%{public}s", funcArg.GetMaxArgc(), str.c_str());
        CallbackType type = CallbackType::UNKNOWN;
        if (str == "stateChange") {
            type = CallbackType::STATE_CHANGE;
        } else if (str == "click") {
            type = CallbackType::CLICK;
        } else {
            LOGE("not support event");
            return nullptr;
        }
        render->player_->ClearCallback(type);
    }
    return nullptr;
}

void PluginRender::Release(std::string &id)
{
    std::shared_ptr<PluginRender> render = PluginRender::GetInstance(id);
    if (nullptr != render) {
        render->surfaceDestroyed_ = true;
    }
}

