    napi_value v1 = funcArg.GetArg(NARG_POS::FIRST);
    NVal nVal(env, v1);
    auto [succ, resStr, length] = nVal.ToUTF8String();
    if (!succ) {
        LOGE("arg type error.");
        return nullptr;
    }
    AnimConfig animConfig;
    animConfig.ParseJson(resStr.get());
