using namespace CommonConst;

void ResourceRequest::SetWidth(uint64_t width) { width_ = width; }

void ResourceRequest::SetHeight(uint64_t height) { height_ = height; }

void ResourceRequest::Create()
{
    cBitmap_ = OH_Drawing_BitmapCreate();
    // 定义bitmap的像素格式
    OH_Drawing_BitmapFormat cFormat{COLOR_FORMAT_RGBA_8888, ALPHA_FORMAT_UNPREMUL};
    // 构造对应格式的bitmap
    OH_Drawing_BitmapBuild(cBitmap_, width_, height_, &cFormat);

    // 创建一个canvas对象
    cCanvas_ = OH_Drawing_CanvasCreate();
    // 将画布与bitmap绑定，画布画的内容会输出到绑定的bitmap内存中
    OH_Drawing_CanvasBind(cCanvas_, cBitmap_);
    // 使用白色清除画布内容
    OH_Drawing_CanvasClear(cCanvas_, OH_Drawing_ColorSetArgb(0x00, 0xFF, 0xFF, 0xAA));
    if (!cBitmap_ || !cCanvas_) {
        LOGE("Create error");
    }
}

OH_Drawing_TextStyle *ResourceRequest::CreateTextStyle(const ColorARGB &color, double fontSize,
    OH_Drawing_FontWeight fontWeight)
{
    OH_Drawing_TextStyle *txtStyle = OH_Drawing_CreateTextStyle();
    OH_Drawing_SetTextStyleColor(txtStyle,
        OH_Drawing_ColorSetArgb(color.alpha, color.red, color.green, color.blue));
    OH_Drawing_SetTextStyleFontSize(txtStyle, fontSize);
    OH_Drawing_SetTextStyleFontWeight(txtStyle, fontWeight);
    OH_Drawing_SetTextStyleBaseLine(txtStyle, TEXT_BASELINE_ALPHABETIC);
    OH_Drawing_SetTextStyleFontHeight(txtStyle, 1);
    OH_Drawing_SetTextStyleFontStyle(txtStyle, FONT_STYLE_NORMAL);
    OH_Drawing_SetTextStyleLocale(txtStyle, "zh");
    return txtStyle;
}

OH_Drawing_Typography *ResourceRequest::CreateTypography(OH_Drawing_TypographyStyle *typoStyle,
    OH_Drawing_FontCollection *fontCollection, OH_Drawing_TextStyle *txtStyle,
    const char *text, double maxWidth)
{
    OH_Drawing_TypographyCreate *handler =
        OH_Drawing_CreateTypographyHandler(typoStyle, fontCollection);
    OH_Drawing_TypographyHandlerPushTextStyle(handler, txtStyle);
    OH_Drawing_TypographyHandlerAddText(handler, text);
    OH_Drawing_TypographyHandlerPopTextStyle(handler);
    OH_Drawing_Typography *typography = OH_Drawing_CreateTypography(handler);
    OH_Drawing_TypographyLayout(typography, maxWidth);
    OH_Drawing_DestroyTypographyHandler(handler);
    return typography;
}

double ResourceRequest::CalculateFittingFontSize(TextOption &txtOpt,
    OH_Drawing_TypographyStyle *typoStyle, OH_Drawing_FontCollection *fontCollection,
    double maxWidth, double maxHeight)
{
    double fontSize = DEFAULT_FONT_SIZE;
    double minFontSize = 8.0;
    bool textFits = false;
    int maxIterations = 50;
    int iteration = 0;
    double textHeightMarginRatio = txtOpt.textHeightMarginRatio > 0 ?
        txtOpt.textHeightMarginRatio : DEFAULT_TEXT_HEIGHT_MARGIN_RATIO;

    while (!textFits && iteration < maxIterations && fontSize >= minFontSize) {
        OH_Drawing_TextStyle *txtStyle = CreateTextStyle(txtOpt.color, fontSize, txtOpt.fontWeight);
        OH_Drawing_Typography *typography = CreateTypography(typoStyle, fontCollection,
            txtStyle, txtOpt.text, maxWidth);
        double textHeight = OH_Drawing_TypographyGetHeight(typography);

        OH_Drawing_DestroyTypography(typography);
        OH_Drawing_DestroyTextStyle(txtStyle);

        if (textHeight <= maxHeight * textHeightMarginRatio) {
            textFits = true;
        } else {
            fontSize = fontSize * FONT_SIZE_REDUCE_RATIO;
        }
        iteration++;
    }

    if (!textFits) {
        fontSize = minFontSize;
        LOGD("Text does not fit, using minFontSize: %{public}f", fontSize);
    } else {
        LOGD("Found fitting fontSize: %{public}f (area: %{public}ldx%{public}ld, "
             "iterations: %{public}d)", fontSize, width_, height_, iteration);
    }
    return fontSize;
}

void ResourceRequest::DrawFinalText(TextOption &txtOpt, OH_Drawing_TypographyStyle *typoStyle,
    OH_Drawing_FontCollection *fontCollection, double fontSize, double maxWidth)
{
    OH_Drawing_TextStyle *txtStyle = CreateTextStyle(txtOpt.color, fontSize, txtOpt.fontWeight);
    OH_Drawing_Typography *typography = CreateTypography(typoStyle, fontCollection,
        txtStyle, txtOpt.text, maxWidth);
    double textHeight = OH_Drawing_TypographyGetHeight(typography);
    double position[2] = {0, (height_ - textHeight) / 2.0};
    OH_Drawing_TypographyPaint(typography, cCanvas_, position[0], position[1]);

    OH_Drawing_DestroyTypography(typography);
    OH_Drawing_DestroyTextStyle(txtStyle);
}

void ResourceRequest::DrawText(TextOption &txtOpt)
{
    OH_Drawing_TypographyStyle *typoStyle = OH_Drawing_CreateTypographyStyle();
    OH_Drawing_SetTypographyTextDirection(typoStyle, TEXT_DIRECTION_LTR);
    OH_Drawing_SetTypographyTextAlign(typoStyle, txtOpt.textAlign);

    if (txtOpt.maxLines > 0) {
        OH_Drawing_SetTypographyTextMaxLines(typoStyle, txtOpt.maxLines);
        OH_Drawing_SetTypographyTextEllipsisModal(typoStyle, ELLIPSIS_MODAL_TAIL);
        OH_Drawing_SetTypographyTextEllipsis(typoStyle, "...");
    }

    ColorARGB color = txtOpt.color;
    LOGD("DrawText color argb: %{public}02x-%{public}02x-%{public}02x-%{public}02x",
        color.alpha, color.red, color.green, color.blue);
    LOGD("DrawText ta fw: %{public}d-%{public}d", txtOpt.fontWeight, txtOpt.textAlign);

    OH_Drawing_FontCollection *fontCollection = OH_Drawing_CreateSharedFontCollection();
    double maxWidth = width_;
    double maxHeight = height_;

    double fontSize = txtOpt.fontSize > 0 ? txtOpt.fontSize :
        CalculateFittingFontSize(txtOpt, typoStyle, fontCollection, maxWidth, maxHeight);
    DrawFinalText(txtOpt, typoStyle, fontCollection, fontSize, maxWidth);

    OH_Drawing_DestroyFontCollection(fontCollection);
    OH_Drawing_DestroyTypographyStyle(typoStyle);
}

void ResourceRequest::GetData(std::vector<uint8_t> &data)
{
    void *bitmapAddr = OH_Drawing_BitmapGetPixels(cBitmap_);

    OH_Drawing_Image_Info info;
    OH_Drawing_BitmapGetImageInfo(cBitmap_, &info);

    uint8_t *value = static_cast<uint8_t *>(bitmapAddr);
    LOGD("GetData data:%{public}d, %{public}ld * %{public}ld %{public}d ** %{public}d", value == nullptr, width_,
         height_, info.width, info.height);
    if (value && width_ > 0 && height_ > 0) {
        LOGD("GetData ok");
    } else {
        LOGE("GetData invalid data");
        return;
    }
    data.assign(value, value + width_ * height_ * FOUR);
}

void ResourceRequest::Release()
{
    if (cCanvas_) {
        // 销毁canvas对象
        OH_Drawing_CanvasDestroy(cCanvas_);
        cCanvas_ = nullptr;
    }
    if (cBitmap_) {
        // 销毁bitmap对象
        OH_Drawing_BitmapDestroy(cBitmap_);
        cBitmap_ = nullptr;
    }
}

static void GetSourceInfo(OH_ImageSourceNative *source, uint32_t &width, uint32_t &height)
{
    OH_ImageSource_Info *imageSrcInfo = nullptr;
    OH_ImageSourceInfo_Create(&imageSrcInfo);
    Image_ErrorCode errCode = OH_ImageSourceNative_GetImageInfo(source, 0, imageSrcInfo);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("FetchImg OH_ImageSourceNative_GetImageInfo failed, errCode: %{public}d.", errCode);
        return;
    }
    OH_ImageSourceInfo_GetWidth(imageSrcInfo, &width);
    OH_ImageSourceInfo_GetHeight(imageSrcInfo, &height);
    LOGD("Open imageSrcInfo:  %{public}d * %{public}d", width, height);
    OH_ImageSourceInfo_Release(imageSrcInfo);
}

static void GetPixelMapInfo(OH_PixelmapNative *resPixMap, uint32_t &height, uint32_t &rowStride)
{
    OH_Pixelmap_ImageInfo *imgInfo = nullptr;
    OH_PixelmapImageInfo_Create(&imgInfo);
    Image_ErrorCode errCode = OH_PixelmapNative_GetImageInfo(resPixMap, imgInfo);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("FetchImg OH_PixelmapNative_GetImageInfo failed, errCode: %{public}d", errCode);
        return;
    }

    int32_t alphaType;
    uint32_t width;
    int32_t pixelFormat;
    OH_PixelmapImageInfo_GetWidth(imgInfo, &width);
    OH_PixelmapImageInfo_GetHeight(imgInfo, &height);
    OH_PixelmapImageInfo_GetRowStride(imgInfo, &rowStride);
    OH_PixelmapImageInfo_GetPixelFormat(imgInfo, &pixelFormat);
    OH_PixelmapImageInfo_GetAlphaType(imgInfo, &alphaType);
    OH_PixelmapImageInfo_Release(imgInfo);
    LOGD("ImagePixelmap GetImageInfo success, width: %{public}d, height: %{public}d, rowStride: "
         "%{public}d, pixelFormat: %{public}d",
         width, height, rowStride, pixelFormat);
}

bool ResourceRequest::HandleFileImg(const MixInputData& mixData, ImageOption &imgOpt, float& scaleX, float& scaleY)
{
    if (mixData.imgUri.empty()) {
        LOGE("FetchImg uri empty");
        return false;
    }
    LOGD("FetchImg OH_ImageSourceNative_CreateFromUri,: %{public}s. %{public}p", mixData.imgUri.c_str(), source_);

    Image_ErrorCode errCode =
        OH_ImageSourceNative_CreateFromUri(const_cast<char *>(mixData.imgUri.c_str()), mixData.imgUri.size(), &source_);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("FetchImg OH_ImageSourceNative_CreateFromUri failed, errCode: %{public}d.", errCode);
        return false;
    }
    uint32_t width = 0;
    uint32_t height = 0;
    GetSourceInfo(source_, width, height);
    // 通过图片解码参数创建PixelMap列表
    OH_DecodingOptions *opts = nullptr;
    OH_DecodingOptions_Create(&opts);
    int32_t pixelFormat = PIXEL_FORMAT_RGBA_8888;
    OH_DecodingOptions_SetPixelFormat(opts, pixelFormat);

    errCode = OH_ImageSourceNative_CreatePixelmap(source_, opts, &resPixMap_);
    OH_DecodingOptions_Release(opts);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("FetchImg OH_ImageSourceNative_CreatePixelmap failed, errCode: %{public}d.", errCode);
        return false;
    }
    if (width == 0 || height == 0) {
        LOGE("FetchImg failed, source width: %u, height: %u", width, height);
        return false;
    }
    scaleX = imgOpt.width / static_cast<float>(width);
    scaleY = imgOpt.height / static_cast<float>(height);
    return true;
}

bool ResourceRequest::HandlePixelImg(const MixInputData& mixData, ImageOption &imgOpt, float& scaleX, float& scaleY)
{
    OH_Pixelmap_ImageInfo* imageInfo = nullptr;
    Image_ErrorCode errCode = OH_PixelmapImageInfo_Create(&imageInfo);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("%{public}s: %{public}d errCode: %{public}d", __FUNCTION__, __LINE__, errCode);
        return false;
    }
    errCode = OH_PixelmapNative_GetImageInfo(mixData.pixelMap, imageInfo);
    if (errCode != IMAGE_SUCCESS) {
        LOGE("%{public}s: %{public}d errCode: %{public}d", __FUNCTION__, __LINE__, errCode);
        OH_PixelmapImageInfo_Release(imageInfo);
        return false;
    }

    uint32_t width = 0;
    uint32_t height = 0;
    errCode = OH_PixelmapImageInfo_GetWidth(imageInfo, &width);
    if (errCode != IMAGE_SUCCESS || width == 0) {
        LOGE("%{public}s: %{public}d errCode: %{public}d", __FUNCTION__, __LINE__, errCode);
        OH_PixelmapImageInfo_Release(imageInfo);
        return false;
    }

    errCode = OH_PixelmapImageInfo_GetHeight(imageInfo, &height);
    if (errCode != IMAGE_SUCCESS || height == 0) {
        LOGE("%{public}s: %{public}d errCode: %{public}d", __FUNCTION__, __LINE__, errCode);
        OH_PixelmapImageInfo_Release(imageInfo);
        return false;
    }

    scaleX = imgOpt.width / static_cast<float>(width);
    scaleY = imgOpt.height / static_cast<float>(height);
    resPixMap_ = mixData.pixelMap;
    OH_PixelmapImageInfo_Release(imageInfo);
    return true;
}

void ResourceRequest::FetchImg(std::vector<uint8_t> &data, ImageOption &imgOpt, const MixInputData& mixData)
{
    Image_ErrorCode errCode;
    float scaleX = 0;
    float scaleY = 0;
    if (mixData.pixelMap == nullptr) {
        if (!HandleFileImg(mixData, imgOpt, scaleX, scaleY)) {
            return;
        }
    } else {
        if (!HandlePixelImg(mixData, imgOpt, scaleX, scaleY)) {
            return;
        }
    }

    errCode = OH_PixelmapNative_Scale(resPixMap_, scaleX, scaleY);
    uint32_t pixelMapHeight;
    uint32_t rowStride;
    GetPixelMapInfo(resPixMap_, pixelMapHeight, rowStride);
    size_t bufferSize = pixelMapHeight * rowStride;
    std::vector<uint8_t> buffer(bufferSize);

    errCode = OH_PixelmapNative_ReadPixels(resPixMap_, buffer.data(), &bufferSize);
    data.assign(buffer.data(), buffer.data() + bufferSize);
    LOGD("OH_PixelmapNative_ReadPixels %{public}lu --- %{public}lu", data.size(), buffer.size());
    OH_PixelmapNative_Release(resPixMap_);
    OH_ImageSourceNative_Release(source_);
    source_ = nullptr;
    resPixMap_ = nullptr;
}

void ResourceRequest::FetchText(std::vector<uint8_t> &data, TextOption &txtOpt)
{
    if (!(txtOpt.text) || txtOpt.height <= 0 || txtOpt.width <= 0) {
        LOGE("FetchText error param");
        return;
    }
    SetWidth(txtOpt.width);
    SetHeight(txtOpt.height);
    Create();
    DrawText(txtOpt);
    GetData(data);
}

