char *MallocCStr(const char *in)
{
    std::size_t len = strlen(in);
    if (len >= MAX_MALLOC_SIZE) {
        return nullptr;
    }
    char *result = static_cast<char *>(malloc(len + 1));
    if (result == nullptr) {
        LOGE("Malloc failed.");
        return nullptr;
    }
    std::char_traits<char>::copy(result, in, len + 1);
    return result;
}
