            processInfo.userId = localAccess.userId;
            processInfo.pkgName = context->GetAclBundleName(context->direction, app);
            processInfoVec.push_back(processInfo);
        }
    }
    context->softbusConnector->SetProcessInfoVec(processInfoVec);
}

