{
    if (context == nullptr) {
        return true;
    }
    auto &targetList = context->isServiceBind ? context->subjectServiceOnes : context->subjectProxyOnes;
    if (!context->IsProxyBind || targetList.empty()) {
        LOGI("no proxy");
        return context->needAuth;
