    std::string pkgName;
    std::string authCode;
    authMgr->GetAuthCodeAndPkgName(pkgName, authCode);
    std::lock_guard<ffrt::mutex> configsLock(configsMapMutex_);
    if (configsMap_.find(tokenId) == configsMap_.end()) {
