        CHECK_NULL_VOID(hiChainAuthConnector_);
        hiChainAuthConnector_->DeleteCredential(udid, MultipleUserConnector::GetCurrentAccountUserID(),
            offlineParam.peerUserId);
    }
    NotifyDeviceOrAppOffline(offlineParam, udid);
}

