        dmAuthInfo.pinExchangeType > DMLocalServiceInfoPinExchangeType::ULTRASOUND) {
        LOGE("Invalid pinExchangeType.");
        return false;
    }
    if (dmAuthInfo.description.length() > DM_PARAM_STRING_LENGTH_MAX) {
        LOGE("Invalid description.");
        return false;
    }
