#if !(defined(__LITEOS_M__) || defined(LITE_DEVICE))
IDeviceProfileConnector* DiscoveryManager::GetCommonDependencyObj()
{
    std::lock_guard<std::mutex> lock(comDependencyLoadLock);
    return dpConnector_;
