constexpr const char* LNN_DISC_CAPABILITY = "capability";
const std::string TYPE_MINE = "findDeviceMode";
const int32_t DECIMALISM = 10;

#if !(defined(__LITEOS_M__) || defined(LITE_DEVICE))
