static bool IsLittleEndian(void)
{
    uint32_t data = 0x1;
    if (data == ntohl(data)) {
        return false;
    } else {
        return true;
    }
}

static void ProcByteOrder(uint8_t *value, int8_t size)
{
    if (IsLittleEndian()) {
        return;
    }
    ShiftByte(value, size);
}

uint8_t SoftBusHtoLss(uint8_t value)
{
    uint8_t res = value;
    ProcByteOrder(&res, (int8_t)sizeof(res));
    return res;
}

