    CONN_CHECK_AND_RETURN_LOGE(
        SoftBusMutexLock(&g_clientSendSignal.sendCondLock) == SOFTBUS_OK, CONN_BLE, "lock fail!");
    g_clientSendSignal.isWriteAvailable = true;
    (void)SoftBusCondBroadcast(&g_clientSendSignal.sendCond);
