    LIST_FOR_EACH_ENTRY_SAFE(it, next, &g_softBusGattsManager.services, ServerService, node) {
        if (it->serviceUuid.uuidLen == serviceUuid.uuidLen &&
            memcmp(it->serviceUuid.uuid, serviceUuid.uuid, it->serviceUuid.uuidLen) == 0) {
            ListDelete(&it->node);
            SoftBusFree(it);
