        CONN_BLE, "lock fail, connId=%{public}d", connId);
    ServerConnection *it = NULL;
    ServerConnection *next = NULL;
    LIST_FOR_EACH_ENTRY_SAFE(it, next, &g_softBusGattsManager.connections, ServerConnection, node) {
        if (it->connId == connId) {
            ListDelete(&it->node);
            SoftBusFree(it);
