            ReleaseSoftBusBcScanFilter(*adapterFilter, size);
            *adapterFilter = NULL;
            return SOFTBUS_INVALID_PARAM;
        }
        ret = CopySoftBusBcScanFilter(tempFilter, (*adapterFilter) + i);
    }

    return ret;
}

