        return ret;
    }
    TRANS_LOGI(TRANS_SVC, "[br_proxy] enter");
    ret = ClientRegisterService(COMM_PKGNAME_PUSH);
    if (ret != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_SDK, "[br_proxy] client register service failed! ret:%{public}d", ret);
