static int32_t ClientRecordListenerState(int32_t channelId, ListenerType type, bool isEnable)
{
    if (g_clientList == NULL) {
        TRANS_LOGE(TRANS_SDK, "[br_proxy] not init");
        return SOFTBUS_NO_INIT;
