    char abilityName[HAP_NAME_MAX_LEN];
    int32_t channelId;
    int32_t appIndex;
    int32_t userId;
    uint32_t requestId;
    pid_t uid;
    pid_t pid;
    bool isEnable;
    bool isConnected;
    bool isVirtualConnect;
    bool isRecovery;
    bool isLastConnect;
    struct ProxyChannel channel;
    ListNode node;
} BrProxyInfo;

typedef struct {
    pid_t callingPid;
    pid_t callingUid;
    uint32_t callingTokenId;
    int32_t channelId;
