            return SOFTBUS_MEM_ERR;
        }
        (void)SoftBusMutexUnlock(&(g_serverList->lock));
        return SOFTBUS_OK;
    }
    (void)SoftBusMutexUnlock(&(g_serverList->lock));
    char *tmpName = NULL;
    Anonymize(brMac, &tmpName);
    TRANS_LOGE(TRANS_SVC, "[br_proxy] update failed! brMac=%{public}s, requestId=%{public}d",
        tmpName, channel->requestId);
