    if (ret != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_SVC, "[br_proxy] get list conut failed! ret:%{public}d", ret);
        return;
    }
    int32_t channelId = 0;
    for (int32_t i = 0; i < count; i++) {
        ret = GetChannelIdFromServerList(&channelId);
        if (ret != SOFTBUS_OK) {
            continue;
        }
        ret = TransCloseBrProxy(channelId, true);
        if (ret != SOFTBUS_OK) {
