        return;
    }
    BrProxyInfo *nodeInfo = NULL;
    LIST_FOR_EACH_ENTRY(nodeInfo, &(g_proxyList->list), BrProxyInfo, node) {
        if (nodeInfo->userId == userId) {
            continue;
        }
        BrProxyInfo *closeInfo = (BrProxyInfo *)SoftBusCalloc(sizeof(BrProxyInfo));
