        return false;
    }
    BrProxyInfo *nodeInfo = NULL;
    LIST_FOR_EACH_ENTRY(nodeInfo, &(g_proxyList->list), BrProxyInfo, node) {
        if (strcmp(bundleName, nodeInfo->bundleName) != 0) {
            continue;
        }
        (void)SoftBusMutexUnlock(&(g_proxyList->lock));
        return true;
    }
    (void)SoftBusMutexUnlock(&(g_proxyList->lock));
