int32_t ConvertErrCode(int32_t error)
{
    switch (error) {
        case ENOSPC:
            return FILE_MANAGER_FILE_ENOSPC;
        case ENOMEM:
            return FILE_MANAGER_FILE_ENOMEM;
        case ENFILE:
