    int32_t delCount = 0;
    SocketWithChannelInfo *socketItem = NULL;
    SocketWithChannelInfo *next = NULL;
    LIST_FOR_EACH_ENTRY_SAFE(socketItem, next, &(g_socketChannelList->list), SocketWithChannelInfo, node) {
        if (socketItem->pid == pid) {
