static int32_t TransProxyResetReplyCnt(int32_t channelId)
{
    TRANS_CHECK_AND_RETURN_RET_LOGE(
        g_proxyChannelList != NULL, SOFTBUS_NO_INIT, TRANS_CTRL, "g_proxyChannelList is null.");
    int32_t ret = SoftBusMutexLock(&g_proxyChannelList->lock);
    TRANS_CHECK_AND_RETURN_RET_LOGE(ret == SOFTBUS_OK, SOFTBUS_LOCK_ERR, TRANS_CTRL, "lock mutex fail!");
    ProxyChannelInfo *item = NULL;
    LIST_FOR_EACH_ENTRY(item, &g_proxyChannelList->list, ProxyChannelInfo, node) {
        if (item->channelId == channelId) {
            item->appInfo.waitOpenReplyCnt = 0;
            (void)SoftBusMutexUnlock(&g_proxyChannelList->lock);
            return SOFTBUS_OK;
        }
    }
    (void)SoftBusMutexUnlock(&g_proxyChannelList->lock);
    TRANS_LOGE(TRANS_CTRL, "proxy channel not found by channelId=%{public}d", channelId);
    return SOFTBUS_TRANS_PROXY_CHANNEL_NOT_FOUND;
}

int32_t TransDealProxyCheckCollabResult(int32_t channelId, int32_t checkResult, pid_t callingPid)
{
    SoftBusHitraceChainBegin("TransDealProxyCheckCollabResult");
    int32_t dmsPid = 0;
    char dmsPkgName[PKG_NAME_SIZE_MAX] = { 0 };
    (void)TransGetPidAndPkgName(DMS_SESSIONNAME, DMS_UID, &dmsPid, dmsPkgName, PKG_NAME_SIZE_MAX);
    if (callingPid != 0 && dmsPid != callingPid) {
        TRANS_LOGE(TRANS_CTRL,
            "dmsPid does not match callingPid, dmsPid=%{public}d, callingPid=%{public}d", dmsPid, callingPid);
        SoftBusHitraceChainEnd();
        return SOFTBUS_TRANS_CHECK_PID_ERROR;
    }

    ProxyChannelInfo chan = { 0 };
    int32_t ret = TransProxyGetChanByChanId(channelId, &chan);
    if (ret != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_CTRL, "get channelInfo failed, channelId=%{public}d.", channelId);
        SoftBusHitraceChainEnd();
        return ret;
    }

    ret = TransProxyUpdateReplyCnt(channelId);
    if (ret != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_CTRL, "update waitOpenReplyCnt failed, channelId=%{public}d.", channelId);
        goto ERR_EXIT;
    }
    // Remove old check tasks.
    TransCheckChannelOpenRemoveFromLooper(channelId);
    if (checkResult != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_CTRL, "check synertistic relation failed, channelId=%{public}d.", channelId);
        ret = checkResult;
        goto ERR_EXIT;
    }
    // Reset the check count to 0.
    ret = TransProxyResetReplyCnt(channelId);
    if (ret != SOFTBUS_OK) {
        goto ERR_EXIT;
    }

    ret = OnProxyChannelOpened(channelId, &(chan.appInfo), PROXY_CHANNEL_SERVER);
    if (ret != SOFTBUS_OK) {
        goto ERR_EXIT;
    }
    SoftBusHitraceChainEnd();
    return SOFTBUS_OK;

ERR_EXIT:
    (void)TransProxyAckHandshake(chan.connId, &chan, ret);
    TransProxyDelChanByChanId(channelId);
    SoftBusHitraceChainEnd();
    return ret;
}

int32_t TransProxyD2dGetSleMac(int32_t channelId, int32_t pid, char *sleMac, uint32_t macLen)
{
    TRANS_CHECK_AND_RETURN_RET_LOGE(sleMac != NULL && macLen > 0 && macLen <= MAC_LEN,
        SOFTBUS_INVALID_PARAM, TRANS_CTRL, "invalid param");

    TRANS_CHECK_AND_RETURN_RET_LOGE(
        g_proxyChannelList != NULL, SOFTBUS_NO_INIT, TRANS_CTRL, "g_proxyChannelList is null");
    TRANS_CHECK_AND_RETURN_RET_LOGE(
        SoftBusMutexLock(&g_proxyChannelList->lock) == SOFTBUS_OK, SOFTBUS_LOCK_ERR, TRANS_CTRL, "lock mutex fail!");
    uint32_t connId = 0;
    ProxyChannelInfo *item = NULL;
    LIST_FOR_EACH_ENTRY(item, &g_proxyChannelList->list, ProxyChannelInfo, node) {
        if (item->channelId == channelId && item->appInfo.myData.pid == pid) {
            connId = item->connId;
            break;
        }
    }
    (void)SoftBusMutexUnlock(&g_proxyChannelList->lock);
    if (connId == 0) {
        return SOFTBUS_TRANS_NODE_NOT_FOUND;
    }
    ConnectOption connOpt;
    (void)memset_s(&connOpt, sizeof(ConnectOption), 0, sizeof(ConnectOption));
    if (TransProxyGetConnInfoByConnId(connId, &connOpt) != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_CTRL, "GetConnectionInfo fail. connId=%{public}u", connId);
        return SOFTBUS_TRANS_NODE_NOT_FOUND;
    }
    if (connOpt.type != CONNECT_SLE) {
        TRANS_LOGE(TRANS_CTRL, "the conn type is not sle. type=%{public}u", connOpt.type);
        return SOFTBUS_TRANS_INVALID_CONNECT_TYPE;
    }
    if (memcpy_s(sleMac, macLen, connOpt.sleOption.address,
        sizeof(connOpt.sleOption.address)) != EOK) {
        return SOFTBUS_MEM_ERR;
    }
    return SOFTBUS_OK;
}

int32_t TransDisableConnBrIdleCheck(int32_t channelId)
{
    TRANS_CHECK_AND_RETURN_RET_LOGE(
        g_proxyChannelList != NULL, SOFTBUS_NO_INIT, TRANS_CTRL, "g_proxyChannelList is null");
    if (SoftBusMutexLock(&g_proxyChannelList->lock) != SOFTBUS_OK) {
        TRANS_LOGE(TRANS_CTRL, "lock mutex fail!");
        return SOFTBUS_LOCK_ERR;
    }
    uint32_t connId = 0;
    ProxyChannelInfo *item = NULL;
    LIST_FOR_EACH_ENTRY(item, &g_proxyChannelList->list, ProxyChannelInfo, node) {
        if (item->channelId == channelId && item->appInfo.linkType == LANE_BR) {
            connId = item->connId;
            break;
        }
    }
    (void)SoftBusMutexUnlock(&g_proxyChannelList->lock);

    UpdateOption option = {
        .type = CONNECT_BR,
        .brOption = {
            .enableIdleCheck = false,
        }
    };
    return ConnUpdateConnection(connId, &option);
}

