        CHECK_COND_WITH_RET_MESSAGE(env, ToAniPhotoAlbumsMap(env, context->albumMap, MapRes) == ANI_OK,
            nullptr, "Failed map -> aniobj options");
    } else {
        ANI_ERR_LOG("GroupByAlbumId failed");
        context->HandleError(env, errorObj);
    }
    tracer.Finish();
    context.reset();
    return MapRes;
}

