    CHECK_COND_WITH_MESSAGE(env,
        MediaLibraryEnumAni::EnumGetValueInt32(env, authorizationMode, authorizationModeInt) == ANI_OK,
        "Failed to call EnumGetValueInt32 for authorizationMode");
