    if (path.find(ROOT_MEDIA_DIR) == string::npos) {
        return false;
    }

    string relativePath = path.substr(ROOT_MEDIA_DIR.size());
    if ((relativePath.find(DOCS_PATH) == 0)) {
        return true;
