    }

    if (fileId.length() > KVSTORE_FILE_ID_TEMPLATE.length() ||
        dateKey.length() > KVSTORE_DATE_KEY_TEMPLATE.length()) {
        MEDIA_ERR_LOG("FileId:%{public}s or dateKey:%{public}s is too long", fileId.c_str(), dateKey.c_str());
