static int64_t GetDatabaseFileSize(const std::string &destFileName)
{
    struct stat statInfo {};
    CHECK_AND_RETURN_RET(stat(destFileName.c_str(), &statInfo) == 0, static_cast<int64_t>(E_OPR_DEBUG_DB_FAIL));
