    const std::string filePath = BETA_DEBUG_DB_FILE_PATH + "media_library_" + betaIssueId + ".db.zip";
    CHECK_AND_PRINT_LOG(MediaFileUtils::DeleteFile(filePath), "Failed to release database file, path: %{private}s",
