        bool isMovingPhotoEffectMode = (fileAsset->GetMovingPhotoEffectMode()) > 0;
        return FileUtils::SaveMovingPhotoVideo(fileAsset->GetFilePath(), isEdited, isMovingPhotoEffectMode);
