    CloneRestoreCVAnalysis cloneRestoreCVAnalysis;
    cloneRestoreCVAnalysis.Init(sceneCode_, taskId_, mediaLibraryRdb_, mediaRdb_, backupRestoreDir_);
    cloneRestoreCVAnalysis.RestoreAlbums(cloneRestoreHighlight);
