// Lomuto分区法 - 简单但效率较低
int LomutoPartition(vector<int> &arr, int low, int high)
{
    int pivot = arr[high]; // 选择最后一个元素作为基准
    int i = low - 1;       // 较小元素的索引
    for (int j = low; j < high; j++) {
        // 如果当前元素小于或等于基准
        if (arr[j] <= pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return i + 1; // 返回基准的最终位置
}

