        int minIndex = i;

        // 在剩余部分中找到最小元素的索引
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }

        // 将找到的最小元素与当前位置交换
        if (minIndex != i) {
            swap(arr[i], arr[minIndex]);
        }
    }
}

