// 基础冒泡排序
void BubbleSortBasic(vector<int> &arr)
{
    int n = arr.size();

    for (int i = 0; i < n - 1; i++) {
        // 每轮将最大的元素"冒泡"到末尾
        for (int j = 0; j < n - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}

