void InsertionSortBasic(vector<int> &arr)
{
    int n = arr.size();

    // 从第二个元素开始（第一个元素视为已排序）
    for (int i = 1; i < n; i++) {
        int key = arr[i]; // 当前要插入的元素
        int j = i - 1;    // 已排序部分的最后一个元素索引

        // 在已排序部分中找到合适位置
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j]; // 元素后移
            j--;
        }

        // 插入元素到正确位置
        arr[j + 1] = key;
    }
}

