// 泛型插入排序模板
template <typename T, typename Compare = std::less<T>>
void InsertionSortTemplate(vector<T> &arr, Compare comp = Compare())
{
    int n = arr.size();

    for (int i = 1; i < n; i++) {
        T key = arr[i];
        int j = i - 1;

        while (j >= 0 && comp(key, arr[j])) {
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = key;
    }
}

