// 插入排序 - 用于小数组优化
void InsertionSort(vector<int> &arr, int low, int high)
{
    for (int i = low + 1; i <= high; i++) {
        int key = arr[i];
        int j = i - 1;

        while (j >= low && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
