void SelectionSortBasic(vector<int> &arr)
{
    int n = arr.size();

    for (int i = 0; i < n - 1; i++) {
        // 假设当前位置是最小值
        int minIndex = i;

        // 在剩余部分中找到最小元素的索引
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }

        // 将找到的最小元素与当前位置交换
        if (minIndex != i) {
            swap(arr[i], arr[minIndex]);
        }
    }
}

