// Hoare分区法 - 效率更高，交换次数更少
int HoarePartition(vector<int> &arr, int low, int high)
{
    int pivot = arr[low + (high - low) / 2]; // 选择中间元素作为基准
    int i = low - 1;
    int j = high + 1;

    while (i < j) {
        // 从左向右找到第一个大于等于基准的元素
        do {
            i++;
        } while (arr[i] < pivot);

        // 从右向左找到第一个小于等于基准的元素
        do {
            j--;
        } while (arr[j] > pivot);

        // 如果指针相遇或交叉，返回分区点
        if (i >= j) {
            return j;
        }

        // 交换这两个元素
        swap(arr[i], arr[j]);
    }
}

// 递归快速排序（Hoare版本）
