// 泛型选择排序模板
template <typename T, typename Compare = std::less<T>>
void SelectionSortTemplate(vector<T> &arr, Compare comp = Compare())
{
    int n = arr.size();

    for (int i = 0; i < n - 1; i++) {
        int targetIndex = i;

        for (int j = i + 1; j < n; j++) {
            if (comp(arr[j], arr[targetIndex])) {
                targetIndex = j;
            }
        }

        if (targetIndex != i) {
            swap(arr[i], arr[targetIndex]);
        }
    }
}

